import awaitWidget from '../../common/awaitWidget';
import getElementById from '../../common/getElementById';
import isObject from '../../common/isObject';
import sendException from '../../exceptions/sendException';

const problems = [
  [
    (hcsNav) => !isObject(hcsNav),
    () => sendException("$('#nav').data('hcsNav') is not an object"),
  ],
  [
    (hcsNav) => !('heights' in hcsNav),
    () => sendException("$('#nav').data('hcsNav').heights does not exist"),
  ],
];

function noProblems(hcsNav) {
  const problem = problems.find(([fn]) => fn(hcsNav));
  if (problem) {
    problem[1]();
    return false;
  }
  return true;
}

export default async function preFlight() {
  const theNav = getElementById('nav');
  const myNav = await awaitWidget(theNav, 'Nav', 'hcs');
  if (noProblems(myNav)) return { theNav, myNav };
  return {};
}
